"""Parser for OpenAI Stream Sentinel markdown and JSON incident reports."""

from __future__ import annotations

import json
import re
from typing import Optional
from post_agi_runbook_synthesizer.models import (
    FailureDomain,
    IngestedIncident,
    Severity,
    TelemetryMetrics,
)


def parse_sentinel_markdown(content: str) -> IngestedIncident:
    """Parse an incident markdown document generated by openai-stream-sentinel."""
    # 1. Incident ID
    inc_match = re.search(r"INC-[A-Z0-9]+", content)
    incident_id = inc_match.group(0) if inc_match else "INC-UNKNOWN"

    # 2. Target Model
    model_match = re.search(r"\*\*Target Model:\*\*\s*`?([a-zA-Z0-9_\-\.]+)`?", content)
    target_model = model_match.group(1) if model_match else "gpt-4o"

    # 3. Failure Domain
    domain_match = re.search(r"\*\*Failure Domain:\*\*\s*`?([A-Z0-9_]+)`?", content)
    raw_domain = domain_match.group(1) if domain_match else "PROXY_BUFFER_BLOAT"
    try:
        domain = FailureDomain(raw_domain)
    except ValueError:
        domain = FailureDomain.CUSTOM

    # 4. Severity
    sev_match = re.search(r"\*\*Severity Classification:\*\*\s*`?([^`\n]+)`?", content)
    raw_sev = sev_match.group(1) if sev_match else ""
    if "SEV-1" in raw_sev:
        severity = Severity.SEV_1
    elif "SEV-2" in raw_sev:
        severity = Severity.SEV_2
    elif "SEV-3" in raw_sev:
        severity = Severity.SEV_3
    else:
        severity = Severity.SEV_3

    # 5. Theoretical Grounding
    theory_match = re.search(r"\*\*Theoretical Grounding:\*\*\s*`?([^`\n]+)`?", content)
    theoretical_grounding = (
        theory_match.group(1)
        if theory_match
        else "MIT 6.033 (Computer System Engineering: Network Buffering)"
    )

    # 6. Summary
    summary_match = re.search(r"## 1\. Executive Summary\s*\n+([^#\n]+)", content)
    if not summary_match:
        summary_match = re.search(r"#### Summary\s*\n+([^#\n]+)", content)
    summary = (
        summary_match.group(1).strip()
        if summary_match
        else "Observed streaming degradation and inter-arrival jitter variance."
    )

    # 7. Telemetry Metrics - flexible matching
    ttft_match = re.search(r"TTFT[^\n]*?`([\d\.]+)\s*ms`", content)
    if not ttft_match:
        ttft_match = re.search(r"TTFT[^\n:]*[:\*]+\s*`?([\d\.]+)", content)

    cadence_match = re.search(r"Token Cadence[^\n]*?`([\d\.]+)\s*tokens/s`", content)
    if not cadence_match:
        cadence_match = re.search(r"Token Cadence[^\n:]*[:\*]+\s*`?([\d\.]+)", content)

    jitter_match = re.search(r"(?:P95|p95)[^\n]*?Jitter[^\n]*?`([\d\.]+)\s*ms`", content)
    if not jitter_match:
        jitter_match = re.search(r"(?:P95|p95)[^\n]*?Jitter[^\n:]*[:\*]+\s*`?([\d\.]+)", content)

    chunks_match = re.search(r"Total Chunks[^\n]*?`(\d+)`", content)
    if not chunks_match:
        chunks_match = re.search(r"Chunks[^\n:]*[:\*]+\s*`?(\d+)`?", content)

    cache_match = re.search(r"Prompt Cache Hit[^\n]*?`(True|False)`", content)
    if not cache_match:
        cache_match = re.search(r"Prompt Cache Hit[^\n:]*[:\*]+\s*`?(True|False)`?", content)

    ttft_ms = float(ttft_match.group(1)) if ttft_match else 250.0
    cadence_tps = float(cadence_match.group(1)) if cadence_match else 20.0
    jitter_ms = float(jitter_match.group(1)) if jitter_match else 15.0
    chunks = int(chunks_match.group(1)) if chunks_match else 30
    cache_hit = (cache_match.group(1) == "True") if cache_match else False

    telemetry = TelemetryMetrics(
        ttft_ms=ttft_ms,
        token_cadence_tps=cadence_tps,
        p95_jitter_ms=jitter_ms,
        chunks_observed=chunks,
        prompt_cache_hit=cache_hit,
        error_rate=0.0 if "5xx" not in content else 0.05,
    )

    # 8. Whys / Invariant notes
    whys = re.findall(r"\d+\.\s+\*Why[^*]+\*\s*([^\n]+)", content)
    actions = re.findall(r"## 5\. Preventative Action Items[^\n]*\n+((?:\d+\..+\n?)+)", content)
    remediation_notes = []
    if actions:
        remediation_notes = [line.strip() for line in actions[0].split("\n") if line.strip()]

    return IngestedIncident(
        incident_id=incident_id,
        title=f"{domain.value} incident on {target_model}",
        target_model=target_model,
        domain=domain,
        severity=severity,
        theoretical_grounding=theoretical_grounding,
        executive_summary=summary,
        telemetry=telemetry,
        whys=whys,
        remediation_notes=remediation_notes,
        raw_markdown=content,
    )


def parse_sentinel_json(json_str: str) -> IngestedIncident:
    data = json.loads(json_str)
    return IngestedIncident(**data)
